using System;
using Avalonia.Controls;
using Avalonia.Input;
using Avalonia.Interactivity;
using CommunityToolkit.Mvvm.ComponentModel;
using CommunityToolkit.Mvvm.Input;
using StarliteDAppWallet.Controls;

namespace StarliteDAppWallet.ViewModels;

/**
 * [dApps View Model]
 * this VM uses webview to display web-native dApps
 * 
 * since it is to handle crypto, Javascript would have to be enabled
 * however, security measures must be in place ensure user safety
 * 
 * the functions of a wallet in a web dApp are:
 *  + inject provider APIs
 *  + sign message & auths
 *  + txn approvals
 * 
 *
 * [glossary]
 * ! [...strutor]
 * ! [.axaml]
 * ! [code-behind]
 * ! [event handlers]
 * ! [class inheritance]
 * ! [records]
 * !
**/
public partial class dAppsViewModel : ContentViewModelBase
{
    /**
     * ! [...strutor] 
     *
    **/

    /** constructor **/

    public dAppsViewModel()
    {
        CurrentWebAddr = string.Empty;

        CurrentWebView = null;

        // BIP39Service.Instance.MnemonicGenerate(128);
    }

    /** destructor **/

    ~dAppsViewModel() {}


    /**
     * ! [.axaml]
     * ! show view properties
    **/

    [ObservableProperty]
    public partial string CurrentWebAddr {get; set;}

    [RelayCommand]
    public void OnCurrentWebAddrEditKey()
    {
        LogService.Debug("enter on web addr");
        
        if (CurrentWebView is null)
        {
            CurrentWebView = new Web3View();
        }
        CurrentWebView.Navigate(new Uri(CurrentWebAddr));
    }

    [RelayCommand]
    public void CommandNavigateBack()
    {
        if (CurrentWebView is null) return;
        if (! CurrentWebView.CanGoBack) return;

        CurrentWebView.GoBack();
    }


    [RelayCommand]
    public void CommandNavigateFore()
    {
        if (CurrentWebView is null) return;
        if (! CurrentWebView.CanGoForward) return;

        CurrentWebView.GoForward();
    }



    /**
     * ! [code-behind]
     * ! the logic to the view
    **/

    [ObservableProperty]
    public partial Web3View? CurrentWebView {get; set;}

    partial void OnCurrentWebViewChanged(Web3View? oldValue, Web3View? newValue)
    {
        if (oldValue is not null) {
            oldValue.NavigationStarted -= OnWebViewNavigationStarted;
            oldValue.NavigationCompleted -= OnWebViewNavigationCompleted;
            oldValue.WebMessageReceived -= OnWebMessageReceived;
            oldValue.NewWindowRequested -= OnWebViewNewWindowRequested;
        }

        if (newValue is null) return;

        LogService.Debug("Invoking WebViewSwitch Event");

        // tells the UI to switch to the CurrentWebView
        WebViewChanged?.Invoke(this, new WebViewSwitchEventArgs(newValue));

        newValue.NavigationStarted += OnWebViewNavigationStarted;
        newValue.NavigationCompleted += OnWebViewNavigationCompleted;
        newValue.WebMessageReceived += OnWebMessageReceived;
        newValue.NewWindowRequested += OnWebViewNewWindowRequested;
    }


    private void OnWebViewNavigationStarted(object? sender, WebViewNavigationStartingEventArgs e) {
        LogService.Debug("WebViewNavigationStarted");

        // chain the event
        // mainly for UI indication of page loading
        CurrentWebViewNavigationStarted?.Invoke(this, EventArgs.Empty);
    }

    private async void OnWebViewNavigationCompleted(object? sender, WebViewNavigationCompletedEventArgs e) {
        LogService.Debug("WebViewNavigationCompleted");

        // chain the event
        // mainly for UI indication of page loading
        CurrentWebViewNavigationCompleted?.Invoke(this, EventArgs.Empty);

        // wait for invokeCSharpAction to be registered in the WebView 
        await ((Web3View)sender!).ScriptBridgeReady();

        await ((Web3View)sender!).InvokeScript(Injection.solana_wallet_standard);
        await ((Web3View)sender!).InvokeScript(Injection.register_wallets);
    }

    private async void OnWebMessageReceived(object? sender, WebMessageReceivedEventArgs e)
    {
        LogService.Debug($"webmessage received > {e.Body}");
    }

    private void OnWebViewNewWindowRequested(object? sender, EventArgs e) {
        LogService.Debug("WebViewNewWindowRequested");
    }



    /**
     * ! [event handlers]
     * ! events that the vm invokes
     * ! events that the main view handles from other vm
    **/

    /** event class with custom parameter **/

    // includes SafeView as a member in EventArgs

    public class WebViewSwitchEventArgs: EventArgs
    {   
        // the unique Id of the selected programme
        public Web3View View;

        // constructor
        public WebViewSwitchEventArgs (Web3View safewebview)
        {
            View = safewebview;
        }
    }

    public event EventHandler<WebViewSwitchEventArgs>? WebViewChanged;
    public event EventHandler? CurrentWebViewNavigationStarted;
    public event EventHandler? CurrentWebViewNavigationCompleted;



    /**
     * ! [class inheritance]
     * ! properties of inherited class
    **/

    // title of the vm
    public override string ViewTitle => "Dummy Profile";

    public override event EventHandler<MainViewModel.SwitchContentEventArgs>? RequestSwitchContentEvent;
    public override event EventHandler? RequestBackContentEvent;
    public override event EventHandler? RequestForeContentEvent;

    public override void OnLeaveEvent() {}

    public override void OnFocusEvent() {}


    /**
     * ! [records]
     * ! where they are meant to be
    **/
}





